excerpts.text:
	on_white_peace = {
		scope:attacker = {
			show_pow_release_message_effect = yes
			stress_and_fulfillment_impact = {
 				ambitious = medium_stress_impact_gain
 				arrogant = medium_stress_impact_gain
 			}
		}

		scope:defender = {
			stress_and_fulfillment_impact = {
 				arrogant = medium_stress_impact_gain
 			}
		}
		hidden_effect = {
			scope:attacker = {
				add_truce_both_ways = {
					character = scope:defender
					days = 1825
					war = root.war
					result = white_peace
				}
			}
		}
		on_white_peace_request_revolt_war = yes
	}

on_defeat = {
	scope:attacker = { show_pow_release_message_effect = yes }
	scope:defender = {
		mandala_peacemaker_perk_serenity_effect = yes
		add_character_flag = {
			flag = recent_liberty_faction_war
			years = 10
		}
		add_dread = medium_dread_gain

		# LEGITIMACY FROM WINNING FACTION WAR
		faction_war_end_victory_legitimacy_effect = yes
	}

	# For revoking titles of character's imprisoned abroard who have lost a revocation war
	hidden_effect = {
		if = {
			limit = {
				scope:attacker = {
					is_imprisoned = yes
					NOT = { is_imprisoned_by = scope:defender }
				}
			}
			scope:defender = {
				add_opinion = {
					target = scope:attacker
					modifier = foreign_prison_revocation_opinion
				}
			}
		}
	}

	on_lost_request_revolt_war = yes

	#Mandalas gain or lose piety/devotion depending on Decree
	mandala_war_defeat_effects = yes

on_lost_request_revolt_war = {
	war = {
		every_war_attacker = {
			limit = {
				exists = liege
				any_liege_or_above = { this = scope:defender }
			}
			if = {
				limit = { is_imprisoned = no }
				hard_imprison_character_effect = {
					TARGET = this
					IMPRISONER = scope:defender
				}
			}
			if = {
				limit = { liege = scope:defender }
				add_faction_cooldown_effect = { YEARS = faction_war_defeat_cooldown }
			}
			scope:defender = {
				add_opinion = {
					target = prev
					modifier = vassal_lost_faction_revolt_war
				}
			}
		}
	}
}

#Add revoke reason to all attackers if they white peace on request war.
on_white_peace_request_revolt_war = {
	war = {
		every_war_attacker = {
			limit = {
				exists = liege
				any_liege_or_above = { this = scope:defender }
			}
			scope:defender = {
				add_opinion = {
					target = prev
					modifier = vassal_wp_faction_revolt_war
				}
			}
			if = {
				limit = { liege = scope:defender }
				add_faction_cooldown_effect = { YEARS = faction_war_white_peace_cooldown }
			}
		}
	}
}
